public class HeadStaffDependencyProbe extends HeadsRegistrationProbe {
 public HeadStaffDependencyProbe(Book b,SortedSet<Integer> ids){super(b,ids);}
 public void process(){super.process();try{
  Object sys=((List<?>)call(sheet,"getSystems")).get(0),sig=call(sys,"getSig"),staff=((List<?>)call(sys,"getStaves")).get(0),table=call(make("sheet.note.DistancesBuilder",sheet),"buildDistances");List<String> controls=new ArrayList<>();
  for(int mode=0;mode<8;mode++){
   Object tally=make("sheet.note.HeadSeedTally"),b=make("sheet.note.NoteHeadsBuilder",sys,table,new ArrayList<>(),tally,Boolean.FALSE,new TreeMap<>());setField(b,"systemBarAreas",new ArrayList<>());setField(b,"systemCompetitors",new ArrayList<>());Object a=make("sheet.note.NoteHeadsBuilder$StaffLineAdapter",b,staff,((List<?>)call(staff,"getLines")).get(0));activeScanner=make("sheet.note.NoteHeadsBuilder$Scanner",b,a,null,0,-4,false);
   List<Map<String,Object>> inputs=new ArrayList<>();
   if(mode!=0){inputs.add(input(50,50,10,10,.7,"NOTEHEAD_BLACK",0.,null,null,0));if(mode!=1)inputs.add(input(mode==6?80:50,mode==7?80:50,10,10,mode==3?.7+5e-6:mode==4?.3:mode==5?.8:.7-5e-6,"NOTEHEAD_BLACK",0.,.5,null,0));}
   List<Object> seeds=new ArrayList<>();for(Map<String,Object> r:inputs)seeds.add(declared(r,staff,sig,tally));List<Object> sorted=new ArrayList<>(seeds);Collections.sort(sorted,(Comparator)Class.forName("org.audiveris.omr.sig.inter.Inters").getField("byFullAbscissa").get(null));Class<?> ipp=Class.forName("org.audiveris.omr.sig.inter.InterPairPredicate");Object predicate=java.lang.reflect.Proxy.newProxyInstance(ipp.getClassLoader(),new Class[]{ipp},(p,m,args)->call(args[0],"isSameAs",args[1]));call(b,"purge",sorted,"previous staff duplicate",predicate,true);call(tally,"purgeRemovedHeads");List<Object> comps=new ArrayList<>(seeds);Collections.sort(comps,(Comparator)Class.forName("org.audiveris.omr.sig.inter.Inters").getField("byOrdinate").get(null));setField(b,"systemCompetitors",comps);List<?> sliced=(List<?>)call(b,"getCompetitorsSlice",new Area(new Rectangle2D.Double(0,52.25,100,5.5)));
   Map<String,Object> proposal=input(50,50,10,10,(.7-2.5e-6)/.9,"NOTEHEAD_VOID",0.,null,null,0);Object head=declared(proposal,staff,sig,tally);List<?> filtered=(List<?>)call(b,"filterSeedConflicts",List.of(head),sliced);List<String> seedRows=new ArrayList<>(),sliceIndices=new ArrayList<>();for(int i=0;i<seeds.size();i++)seedRows.add(record(seeds.get(i)).replaceFirst("\\{","{\"removed\":"+call(seeds.get(i),"isRemoved")+","));for(Object c:sliced)sliceIndices.add(""+seeds.indexOf(c));controls.add("{\"mode\":"+mode+",\"seed_inputs\":"+encode(inputs)+",\"seed_after_previous_staff\":["+String.join(",",seedRows)+"],\"slice_indices\":["+String.join(",",sliceIndices)+"],\"line\":[[0,55],[100,55]],\"interline\":11,\"dir\":0,\"proposal\":"+encode(proposal)+",\"accepted\":"+!filtered.isEmpty()+"}");call(head,"remove");for(Object h:seeds)if(!Boolean.TRUE.equals(call(h,"isRemoved")))call(h,"remove");
  }
  Files.writeString(Path.of(System.getProperty("native.probe.output")).resolveSibling("staff-dependency-controls.json"),"{\"native_outputs_used\":false,\"scope\":\"Unmodified original previous-staff duplicate purge then Inters.intersectedInters/NoteHeadsBuilder.getCompetitorsSlice/filterSeedConflicts. Removed good seed at threshold must not veto the next staff.\",\"controls\":["+String.join(",",controls)+"]}\n");
 }catch(Exception e){throw new RuntimeException(e);}}
}
